insert into public.flashcards (id, cert, deck, domain, objective, front, back) values
('sa-f-063','awssaa','core',1,'1.1',$$What is a VPC endpoint policy vs an IAM policy for S3 access?$$,$$Both are evaluated together; the endpoint policy restricts what the endpoint itself allows through, while IAM policies control what the calling identity is allowed to do - access requires both to permit it.$$),
('sa-f-064','awssaa','core',1,'1.1',$$What is AWS Organizations SCP inheritance?$$,$$SCPs attached to an OU apply to all accounts and nested OUs beneath it; the effective permission set is the intersection of all SCPs from root down to the account.$$),
('sa-f-065','awssaa','core',1,'1.2',$$What is AWS Secrets Manager automatic rotation?$$,$$A Lambda function AWS (or you) provides rotates a secret (like an RDS password) on a schedule and updates both the secret store and the target service atomically.$$),
('sa-f-066','awssaa','core',1,'1.2',$$What is KMS multi-region key replication used for?$$,$$Encrypting/decrypting the same data consistently across regions (e.g., for DR or global apps) without re-encrypting data when moving between regions - each region gets a related but independent key.$$),
('sa-f-067','awssaa','core',1,'1.1',$$What is an S3 Access Point?$$,$$A named network endpoint with its own policy attached to a bucket, simplifying access management for shared buckets with many different applications/teams needing different permissions.$$),
('sa-f-068','awssaa','core',1,'1.1',$$What does AWS Config's conformance pack provide?$$,$$A packaged set of Config rules mapped to a compliance framework, deployable across accounts to continuously check configuration against that standard.$$),
('sa-f-069','awssaa','core',1,'1.1',$$What is the AWS Well-Architected Framework's Security pillar focus?$$,$$Identity and access management, detective controls, infrastructure protection, data protection, and incident response - a structured lens for reviewing architecture security.$$),
('sa-f-070','awssaa','core',1,'1.1',$$What is VPC flow log filtering used for in security review?$$,$$Selectively capturing ACCEPT, REJECT, or ALL traffic at ENI/subnet/VPC level to control log volume and cost while still catching what's operationally relevant.$$),
('sa-f-071','awssaa','core',1,'1.2',$$What is envelope encryption's benefit when encrypting large S3 objects with KMS?$$,$$Only a small data key (not the full object) is sent to KMS for encryption/decryption, avoiding KMS API throughput limits and keeping the master key's exposure minimal.$$),
('sa-f-072','awssaa','core',2,'2.1',$$What is a Transit Gateway and when is it preferred over VPC peering?$$,$$A central hub connecting many VPCs/VPNs through one attachment point; preferred over peering once you have more than a handful of VPCs, since peering doesn't scale (no transitive routing, N-squared connections).$$),
('sa-f-073','awssaa','core',2,'2.1',$$What is Route 53 failover routing policy?$$,$$Routes to a primary endpoint while it's healthy (via health check) and automatically fails over to a secondary endpoint when it isn't - a DNS-level HA mechanism.$$),
('sa-f-074','awssaa','core',2,'2.1',$$What is Route 53 weighted routing used for?$$,$$Splitting traffic between multiple endpoints by assigned weight - useful for canary/blue-green deployments and gradual traffic shifting.$$),
('sa-f-075','awssaa','core',2,'2.2',$$What is RDS Proxy and its resilience benefit?$$,$$A managed connection pooler in front of RDS/Aurora; it holds connections open through a failover so the application doesn't need to re-establish a fresh connection storm, reducing failover impact.$$),
('sa-f-076','awssaa','core',2,'2.2',$$What is Aurora Global Database?$$,$$A primary region with fast (typically under 1s) replication to up to 5 secondary read regions, enabling low-latency global reads and fast regional disaster recovery promotion.$$),
('sa-f-077','awssaa','core',2,'2.1',$$What is a NAT Gateway's availability limitation and the fix?$$,$$A NAT Gateway is scoped to a single AZ; deploy one per AZ (each in its own public subnet) so an AZ failure doesn't take down outbound internet access for the whole VPC.$$),
('sa-f-078','awssaa','core',2,'2.2',$$What is S3 Same-Region Replication (SRR) used for, distinct from Cross-Region Replication?$$,$$Compliance/data residency copies, log aggregation across buckets, or replicating between production and test accounts within the same region.$$),
('sa-f-079','awssaa','core',2,'2.1',$$What is EventBridge and its resilience use case?$$,$$A serverless event bus that decouples producers and consumers with routing rules; failed deliveries can retry or route to a dead-letter queue, preventing event loss.$$),
('sa-f-080','awssaa','core',3,'3.2',$$What is DynamoDB DAX?$$,$$An in-memory caching layer specifically for DynamoDB, delivering microsecond read latency for read-heavy workloads without significant application code changes.$$),
('sa-f-081','awssaa','core',3,'3.1',$$What is AWS Global Accelerator and how does it differ from CloudFront?$$,$$Global Accelerator improves performance for TCP/UDP traffic (including non-HTTP) via Anycast IPs routed over the AWS backbone; CloudFront is an HTTP(S)-focused CDN with edge caching.$$),
('sa-f-082','awssaa','core',3,'3.2',$$What is DynamoDB auto scaling?$$,$$Automatically adjusts provisioned read/write capacity based on utilization targets, or use on-demand mode to skip capacity planning entirely for unpredictable workloads.$$),
('sa-f-083','awssaa','core',3,'3.1',$$What is ECS Fargate vs ECS on EC2?$$,$$Fargate: serverless containers, AWS manages the underlying compute, pay per task. EC2 launch type: you manage the underlying instances, more control, potentially cheaper at scale.$$),
('sa-f-084','awssaa','core',3,'3.2',$$What is Aurora Serverless v2 used for?$$,$$Automatically scaling database capacity up/down (including to near-zero) based on load, ideal for variable or infrequent workloads without manual capacity planning.$$),
('sa-f-085','awssaa','core',3,'3.1',$$What is S3 Multipart Upload used for?$$,$$Uploading large objects in parallel parts, improving throughput and allowing resume of a failed upload without restarting from zero.$$),
('sa-f-086','awssaa','core',3,'3.2',$$What is ElastiCache cluster mode (Redis)?$$,$$Shards data across multiple nodes for horizontal scaling of both storage and throughput, versus a single-shard cluster limited to one primary node's capacity.$$),
('sa-f-087','awssaa','core',4,'4.1',$$What is AWS Compute Optimizer?$$,$$Analyzes utilization metrics and recommends right-sized instance types/sizes for EC2, EBS, Lambda, and ASGs to eliminate over-provisioning cost.$$),
('sa-f-088','awssaa','core',4,'4.2',$$What is S3 Requester Pays used for?$$,$$Shifts data transfer/request costs to whoever downloads the object instead of the bucket owner - useful for publicly shared large datasets.$$),
('sa-f-089','awssaa','core',4,'4.1',$$What is a Compute Savings Plan vs an EC2 Instance Savings Plan?$$,$$Compute Savings Plans apply flexibly across instance families, regions, and even Lambda/Fargate; EC2 Instance Savings Plans lock in a specific instance family/region for a bigger discount.$$),
('sa-f-090','awssaa','core',4,'4.2',$$What is AWS Budgets Actions?$$,$$Automated responses (like applying a restrictive IAM policy or stopping instances) triggered when spend crosses a defined budget threshold, not just an alert.$$),
('sa-f-091','awssaa','core',4,'4.1',$$Why is Aurora Serverless cost-efficient for infrequent workloads?$$,$$It scales capacity down to near-zero during idle periods and back up on demand, so you aren't paying for a fixed-size always-on database that sits mostly idle.$$),
('sa-f-092','awssaa','core',4,'4.2',$$What is the cost trade-off of S3 Intelligent-Tiering's monitoring fee?$$,$$A small per-object monitoring fee is charged in exchange for automatic tier movement - worth it when access patterns are unpredictable, wasteful for objects with a known, stable access pattern.$$);
insert into public.questions (id, cert, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
('sa-q-061','awssaa',1,'1.1','mcq',2,$q$A shared VPC endpoint policy allows access to only two specific S3 buckets, but an IAM policy attached to a role grants s3:* on all buckets. What access does a principal using that role actually have through the endpoint?$q$,$q$["Full access to all buckets, since IAM is authoritative","Access limited to the two buckets the endpoint policy allows, since both policies must permit the request","No access at all","Access determined randomly"]$q$::jsonb,'1'::jsonb,$q$Both the endpoint policy and IAM policy are evaluated, and access requires both to permit it - the endpoint policy caps what's reachable regardless of how broad the IAM grant is.$q$),
('sa-q-062','awssaa',1,'1.1','mcq',2,$q$An SCP is attached to the root of an AWS Organization denying all EC2 usage outside us-east-1. A specific account also has an IAM policy allowing EC2 in eu-west-1. What is the effective permission?$q$,$q$["EC2 is allowed in eu-west-1 because the IAM policy is more specific","EC2 is denied in eu-west-1 because the SCP applies to every account beneath it and explicit deny always wins","The account can choose which policy to follow","SCPs never apply to already-existing IAM policies"]$q$::jsonb,'1'::jsonb,$q$SCPs cap what every account beneath them can do regardless of local IAM grants, and an explicit deny always overrides an allow anywhere in the evaluation.$q$),
('sa-q-063','awssaa',1,'1.2','mcq',2,$q$A DBA rotates RDS database credentials manually every quarter, causing application outages when the password changes are missed. Which AWS service automates this safely?$q$,$q$["AWS Secrets Manager with automatic rotation","Amazon S3 versioning","AWS Config","Amazon CloudWatch Logs"]$q$::jsonb,'0'::jsonb,$q$Secrets Manager's automatic rotation updates both the secret store and the target database atomically on a schedule, eliminating manual, error-prone rotation.$q$),
('sa-q-064','awssaa',1,'1.2','mcq',3,$q$A global application needs to encrypt data consistently in both us-east-1 and eu-west-1 without re-encrypting objects when they move between regions. Which KMS feature fits?$q$,$q$["A single-region KMS key shared over the internet","Multi-region KMS keys","S3 default encryption alone","IAM policies only"]$q$::jsonb,'1'::jsonb,$q$Multi-region KMS keys are related keys with the same key material replicated across regions, letting ciphertext encrypted in one region be decrypted in another without re-encryption.$q$),
('sa-q-065','awssaa',1,'1.1','mcq',2,$q$A company has one S3 bucket shared by ten different applications, each needing different permissions. Managing one giant bucket policy has become unmanageable. What AWS feature simplifies this?$q$,$q$["S3 Access Points, each with its own scoped policy","Deleting the bucket and starting over","IAM users for each application","CloudFront only"]$q$::jsonb,'0'::jsonb,$q$Access Points let you create multiple named endpoints on one bucket, each with its own simpler policy scoped to a specific application's needs.$q$),
('sa-q-066','awssaa',1,'1.1','mcq',2,$q$A company must continuously verify that every S3 bucket in 50 AWS accounts meets a specific compliance framework's encryption and public-access requirements. What should they deploy?$q$,$q$["Manual quarterly spreadsheets","An AWS Config conformance pack deployed across accounts","A single IAM policy","CloudFront logging"]$q$::jsonb,'1'::jsonb,$q$A conformance pack bundles Config rules mapped to a framework and deploys them consistently across many accounts for continuous, automated compliance checking.$q$),
('sa-q-067','awssaa',1,'1.1','mcq',2,$q$Which Well-Architected Framework pillar specifically addresses identity and access management, detective controls, and incident response?$q$,$q$["Cost Optimization","Security","Performance Efficiency","Operational Excellence"]$q$::jsonb,'1'::jsonb,$q$The Security pillar covers IAM, detective controls, infrastructure/data protection, and incident response as its core focus areas.$q$),
('sa-q-068','awssaa',1,'1.1','mcq',2,$q$A security team wants to capture only REJECTED connection attempts in VPC Flow Logs to control log volume while still catching blocked malicious traffic. What should they configure?$q$,$q$["Flow log filter set to REJECT traffic only","Capturing ALL traffic with no filter","Disabling flow logs entirely","CloudTrail instead of flow logs"]$q$::jsonb,'0'::jsonb,$q$Flow logs can be filtered to ACCEPT, REJECT, or ALL traffic; filtering to REJECT-only captures blocked attempts while controlling log volume and cost.$q$),
('sa-q-069','awssaa',1,'1.2','mcq',2,$q$Why does KMS use envelope encryption when encrypting a large S3 object rather than sending the whole object to KMS?$q$,$q$["KMS cannot encrypt any data directly","Sending only a small data key to KMS avoids API throughput limits and keeps the master key's exposure minimal","Envelope encryption is required by AWS for all API calls","It makes the object larger for no reason"]$q$::jsonb,'1'::jsonb,$q$Only the small data key transits KMS; the object itself is encrypted locally with that key, avoiding KMS throughput limits and minimizing master key exposure.$q$),
('sa-q-070','awssaa',1,'1.1','mcq',3,$q$An application needs to reach DynamoDB from a private subnet without traversing the internet or incurring NAT Gateway data charges. What should be configured?$q$,$q$["A DynamoDB Gateway VPC endpoint","A public IP on the instance","An Internet Gateway route","A second NAT Gateway"]$q$::jsonb,'0'::jsonb,$q$A Gateway VPC endpoint for DynamoDB routes traffic privately within the VPC, bypassing both the internet and NAT Gateway data-processing charges.$q$),
('sa-q-071','awssaa',1,'1.1','mcq',2,$q$Which combination enforces that S3 objects can only be uploaded if encrypted with a specific KMS key, rejecting all other requests?$q$,$q$["A bucket policy denying PutObject unless the correct KMS key ID is specified in the request","Enabling versioning only","A CloudFront distribution","Using HTTP instead of HTTPS"]$q$::jsonb,'0'::jsonb,$q$A bucket policy condition checking the KMS key ID on PutObject enforces that only objects encrypted with the approved key can be uploaded.$q$),
('sa-q-072','awssaa',1,'1.1','matching',2,$q$Match each AWS security feature to its function.$q$,$q${"left":["S3 Access Point","KMS multi-region key","Secrets Manager rotation","Config conformance pack"],"right":["Scoped access endpoint for a shared bucket","Consistent encryption across regions without re-encrypting","Automated credential rotation","Continuous compliance checks against a framework"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Access Points scope bucket access; multi-region keys enable cross-region encryption consistency; Secrets Manager automates rotation; conformance packs enforce continuous compliance.$q$),
('sa-q-073','awssaa',1,'1.1','mcq',2,$q$A company wants every new AWS account created in their Organization to automatically inherit a baseline set of guardrails without manual setup. Which service provides this?$q$,$q$["AWS Control Tower","Amazon S3","AWS Lambda","Amazon Route 53"]$q$::jsonb,'0'::jsonb,$q$Control Tower automatically applies preventive and detective guardrails to new accounts provisioned through its account factory, ensuring baseline governance from day one.$q$),
('sa-q-074','awssaa',1,'1.2','mcq',2,$q$Which statement about SCPs and IAM permission boundaries is correct?$q$,$q$["Both grant permissions directly","Neither grants permissions; both act as ceilings that cap what identity policies within their scope can allow","SCPs apply to individual users only, never accounts","Permission boundaries apply org-wide like SCPs"]$q$::jsonb,'1'::jsonb,$q$Neither SCPs nor permission boundaries grant access - they both cap the maximum permissions that identity policies within their scope (account-wide or per-identity) can actually allow.$q$),
('sa-q-075','awssaa',2,'2.1','mcq',2,$q$A company has grown from 3 VPCs to 40 VPCs, and full-mesh VPC peering has become impossible to manage. What should they migrate to?$q$,$q$["More VPC peering connections","AWS Transit Gateway as a central hub","A single larger VPC","Deleting excess VPCs"]$q$::jsonb,'1'::jsonb,$q$Transit Gateway replaces N-squared peering connections with one central hub each VPC attaches to once, scaling far better as VPC count grows.$q$),
('sa-q-076','awssaa',2,'2.1','mcq',2,$q$Which Route 53 routing policy automatically stops sending traffic to an endpoint that fails its health check and redirects it to a healthy standby?$q$,$q$["Simple routing","Failover routing","Geolocation routing","Weighted routing with equal weights"]$q$::jsonb,'1'::jsonb,$q$Failover routing is purpose-built for this exact primary/secondary health-check-driven pattern.$q$),
('sa-q-077','awssaa',2,'2.1','mcq',2,$q$A team wants to gradually shift 10% of production traffic to a new application version before a full rollout. Which Route 53 policy fits?$q$,$q$["Weighted routing","Latency routing","Simple routing","Geoproximity routing"]$q$::jsonb,'0'::jsonb,$q$Weighted routing splits traffic between endpoints by assigned proportion, ideal for gradual canary rollouts.$q$),
('sa-q-078','awssaa',2,'2.2','mcq',3,$q$An application experiences a burst of connection errors every time RDS fails over, because it must re-establish hundreds of fresh connections simultaneously. Which service reduces this impact?$q$,$q$["RDS Proxy, which holds pooled connections open through failover","A larger RDS instance","S3 Transfer Acceleration","AWS Budgets"]$q$::jsonb,'0'::jsonb,$q$RDS Proxy pools and holds connections, smoothing over failover so the application doesn't need to reconnect en masse.$q$),
('sa-q-079','awssaa',2,'2.2','mcq',2,$q$A globally distributed application needs sub-second read replication to five regions plus fast regional failover for disaster recovery. Which database feature fits?$q$,$q$["Aurora Global Database","A single-region RDS instance","DynamoDB Local","S3 Cross-Region Replication"]$q$::jsonb,'0'::jsonb,$q$Aurora Global Database is purpose-built for this: sub-second replication to up to 5 secondary regions with fast promotion for DR.$q$),
('sa-q-080','awssaa',2,'2.1','mcq',3,$q$A NAT Gateway in a single AZ fails, and every private-subnet instance in the VPC loses outbound internet access, even those in other AZs. What design flaw caused this?$q$,$q$["Only one NAT Gateway was deployed instead of one per AZ","NAT Gateways cannot fail","The VPC has too many subnets","This is expected and cannot be fixed"]$q$::jsonb,'0'::jsonb,$q$A NAT Gateway is AZ-scoped; deploying only one creates a single point of failure for outbound access across the whole VPC - one per AZ avoids this.$q$),
('sa-q-081','awssaa',2,'2.2','mcq',2,$q$A company needs to copy specific S3 objects between two buckets in the SAME region for compliance record-keeping, without cross-region latency or cost. What feature fits?$q$,$q$["Same-Region Replication (SRR)","Cross-Region Replication (CRR) only","EBS snapshots","CloudFront"]$q$::jsonb,'0'::jsonb,$q$SRR replicates objects between buckets within the same region - exactly this compliance/record-keeping use case without CRR's cross-region overhead.$q$),
('sa-q-082','awssaa',2,'2.1','mcq',2,$q$A serverless order-processing pipeline needs to decouple event producers from consumers, route different event types to different targets, and retry failed deliveries via a dead-letter queue. Which service fits?$q$,$q$["Amazon EventBridge","A single Lambda function with no queue","EBS","Route 53"]$q$::jsonb,'0'::jsonb,$q$EventBridge is built for exactly this: decoupled event routing with rules per event type and DLQ support for failed deliveries.$q$),
('sa-q-083','awssaa',2,'2.1','mcq',2,$q$Which AWS service should be used to connect an on-premises data center to a VPC with a dedicated, private, high-bandwidth connection instead of over the public internet?$q$,$q$["AWS Direct Connect","A NAT Gateway","An internet-facing ALB","S3 Transfer Acceleration"]$q$::jsonb,'0'::jsonb,$q$Direct Connect provides a dedicated private network connection between on-premises and AWS, bypassing the public internet entirely.$q$),
('sa-q-084','awssaa',2,'2.2','mcq',2,$q$Why does a stateless application tier improve resilience during an Auto Scaling event?$q$,$q$["Any instance can serve any request and be freely replaced, since session state lives externally (DynamoDB/ElastiCache) rather than on the instance","Stateless instances are always faster","Stateless design eliminates the need for load balancers","Stateless design removes the need for redundancy"]$q$::jsonb,'0'::jsonb,$q$Externalizing session state means instances are interchangeable - Auto Scaling can add, remove, or replace them freely without losing user sessions.$q$),
('sa-q-085','awssaa',2,'2.1','ordering',2,$q$Order these VPC connectivity options from SIMPLEST (few VPCs) to MOST SCALABLE (many VPCs/on-prem sites).$q$,$q$["VPC Peering (point-to-point)","Transit Gateway (central hub)","Transit Gateway with Direct Connect Gateway (hybrid multi-site)"]$q$::jsonb,$q$[0,1,2]$q$::jsonb,$q$Peering suits a handful of VPCs; Transit Gateway centralizes many VPCs; adding Direct Connect Gateway extends that hub to multiple on-premises sites at hybrid scale.$q$),
('sa-q-086','awssaa',2,'2.2','mcq',2,$q$A read-heavy application queries the same product catalog data thousands of times per second from DynamoDB, driving up read costs and latency. Which addition helps most?$q$,$q$["DynamoDB Accelerator (DAX) for in-memory caching","Switching to RDS","Disabling DynamoDB auto scaling","Adding more Availability Zones"]$q$::jsonb,'0'::jsonb,$q$DAX caches hot reads in memory in front of DynamoDB, cutting both cost and latency for exactly this repeated-read pattern.$q$),
('sa-q-087','awssaa',3,'3.1','mcq',2,$q$A gaming company needs the lowest possible latency for a UDP-based multiplayer game routed over AWS's global network, not just HTTP content caching. Which service fits best?$q$,$q$["Amazon CloudFront","AWS Global Accelerator","S3 Transfer Acceleration","Route 53 latency routing alone"]$q$::jsonb,'1'::jsonb,$q$Global Accelerator optimizes TCP/UDP traffic (not just HTTP) over the AWS backbone via Anycast IPs - exactly the fit for a non-HTTP, latency-sensitive protocol.$q$),
('sa-q-088','awssaa',3,'3.2','mcq',2,$q$An unpredictable workload sometimes needs zero database capacity and sometimes needs a large burst. Which Aurora option avoids manual capacity planning entirely?$q$,$q$["Aurora Serverless v2","A fixed-size db.r5.24xlarge instance always running","Aurora with Multi-AZ only","RDS on a t2.micro"]$q$::jsonb,'0'::jsonb,$q$Serverless v2 automatically scales capacity, including down to near-zero, matching genuinely unpredictable demand without manual sizing.$q$),
('sa-q-089','awssaa',3,'3.1','mcq',2,$q$Which ECS launch type removes the need to provision or patch any underlying EC2 instances?$q$,$q$["EC2 launch type","Fargate launch type","On-premises launch type","There is no such option"]$q$::jsonb,'1'::jsonb,$q$Fargate is serverless container compute - AWS manages the underlying infrastructure entirely, unlike the EC2 launch type.$q$),
('sa-q-090','awssaa',3,'3.2','mcq',2,$q$A DynamoDB table experiences highly unpredictable traffic spikes that are hard to forecast. Which capacity mode avoids both under- and over-provisioning?$q$,$q$["Provisioned capacity with manual adjustment only","On-demand capacity mode","A fixed read/write capacity with no scaling","Disabling auto scaling"]$q$::jsonb,'1'::jsonb,$q$On-demand mode charges per request and scales instantly, sidestepping the guesswork of provisioned capacity planning for unpredictable traffic.$q$),
('sa-q-091','awssaa',3,'3.1','mcq',2,$q$Uploading a 50 GB file to S3 over an unreliable connection keeps failing partway through, forcing a full restart each time. Which S3 feature avoids restarting from zero?$q$,$q$["Multipart upload, which uploads in parallel parts and can resume failed parts","S3 Versioning","S3 Lifecycle policies","Bucket policies"]$q$::jsonb,'0'::jsonb,$q$Multipart upload breaks the object into independently-uploaded parts, so only failed parts need retrying rather than the entire object.$q$),
('sa-q-092','awssaa',3,'3.2','mcq',3,$q$A Redis-based caching layer has outgrown a single node's memory and throughput capacity. Which ElastiCache feature scales this horizontally?$q$,$q$["Cluster mode, sharding data across multiple nodes","A larger single node with no sharding","Switching to Memcached automatically","Disabling replication"]$q$::jsonb,'0'::jsonb,$q$Cluster mode shards data across multiple nodes, scaling both storage and throughput beyond what a single-shard cluster can provide.$q$),
('sa-q-093','awssaa',3,'3.1','mcq',2,$q$Which service combination delivers both HTTP content caching at edge locations AND accelerated non-HTTP TCP/UDP traffic for a hybrid application?$q$,$q$["CloudFront for HTTP content, Global Accelerator for TCP/UDP traffic","CloudFront alone handles both","Global Accelerator alone handles both","Neither service is needed"]$q$::jsonb,'0'::jsonb,$q$Each service specializes: CloudFront for HTTP(S) edge caching, Global Accelerator for broader TCP/UDP acceleration - combining them covers both traffic types.$q$),
('sa-q-094','awssaa',3,'3.2','mcq',2,$q$Which read-scaling technique lets a busy RDS database offload read queries without impacting the write path?$q$,$q$["Read replicas","Increasing the primary instance's storage only","Disabling automated backups","Reducing the number of AZs"]$q$::jsonb,'0'::jsonb,$q$Read replicas asynchronously copy the primary and serve read traffic separately, scaling reads without touching the write path.$q$),
('sa-q-095','awssaa',3,'3.1','mcq',2,$q$A company wants to run traditional server-based containers but retain full control over the underlying EC2 instances for custom AMI requirements. Which ECS launch type fits?$q$,$q$["Fargate","EC2 launch type","Lambda","There is no such option"]$q$::jsonb,'1'::jsonb,$q$The EC2 launch type gives full control over the underlying instances (custom AMIs, instance types), unlike Fargate's fully managed compute.$q$),
('sa-q-096','awssaa',3,'3.2','mcq',2,$q$What EBS volume type is optimized for large, sequential throughput workloads like big data processing, rather than high random IOPS?$q$,$q$["gp3 General Purpose SSD","io2 Provisioned IOPS SSD","st1 Throughput Optimized HDD","Instance store"]$q$::jsonb,'2'::jsonb,$q$st1 is purpose-built for large sequential throughput workloads at lower cost than SSD options, which target random IOPS performance instead.$q$),
('sa-q-097','awssaa',3,'3.1','mcq',3,$q$An application needs consistent single-digit-millisecond latency at any scale for a key-value access pattern, without managing servers. Which combination fits best?$q$,$q$["DynamoDB with on-demand capacity","RDS with a large instance","EC2 with a self-managed database","Redshift"]$q$::jsonb,'0'::jsonb,$q$DynamoDB delivers consistent single-digit-millisecond latency at any scale for key-value access, fully serverless - exactly this requirement.$q$),
('sa-q-098','awssaa',4,'4.1','mcq',2,$q$An organization wants automated recommendations for right-sizing over-provisioned EC2 instances and EBS volumes based on actual utilization. Which tool fits?$q$,$q$["AWS Compute Optimizer","AWS Config","Amazon Route 53","AWS Direct Connect"]$q$::jsonb,'0'::jsonb,$q$Compute Optimizer analyzes utilization metrics and recommends right-sized resources across EC2, EBS, Lambda, and ASGs.$q$),
('sa-q-099','awssaa',4,'4.2','mcq',2,$q$A research organization publishes a large public dataset in S3 and wants downloaders to pay for their own data transfer instead of the org absorbing the cost. What should they enable?$q$,$q$["S3 Requester Pays","S3 Versioning","S3 Intelligent-Tiering","CloudFront caching"]$q$::jsonb,'0'::jsonb,$q$Requester Pays shifts data transfer and request costs to the downloader rather than the bucket owner, ideal for widely shared public datasets.$q$),
('sa-q-100','awssaa',4,'4.1','mcq',2,$q$A company runs a steady workload split across multiple instance families and regions and wants the most FLEXIBLE savings commitment. Which option fits best?$q$,$q$["A Compute Savings Plan","An EC2 Instance Savings Plan locked to one family","On-Demand pricing only","Dedicated Hosts"]$q$::jsonb,'0'::jsonb,$q$Compute Savings Plans apply flexibly across instance families, regions, and even serverless compute, unlike the narrower Instance Savings Plan commitment.$q$),
('sa-q-101','awssaa',4,'4.2','mcq',2,$q$A company wants an automatic action - like applying a restrictive IAM policy - to trigger the moment monthly AWS spend crosses a defined threshold, not just an email alert. What should they configure?$q$,$q$["AWS Budgets Actions","Cost Explorer alone","CloudTrail","A manual spreadsheet"]$q$::jsonb,'0'::jsonb,$q$Budgets Actions goes beyond alerting to trigger automated responses (policy changes, instance stops) when spend crosses a threshold.$q$),
('sa-q-102','awssaa',4,'4.1','mcq',2,$q$Why is Aurora Serverless cost-efficient for a workload that is idle most of the day with occasional bursts?$q$,$q$["It scales capacity down to near-zero when idle and back up on demand, avoiding payment for an always-on fixed-size database","It is always more expensive than provisioned Aurora","It requires manual capacity planning","It disables backups to save cost"]$q$::jsonb,'0'::jsonb,$q$Scaling to near-zero during idle periods directly avoids paying for unused fixed capacity, the core cost advantage for this usage pattern.$q$),
('sa-q-103','awssaa',4,'4.2','mcq',3,$q$A dataset has a completely unpredictable access pattern - sometimes accessed daily, sometimes untouched for months. Storing it in S3 Standard-IA risks retrieval fees on unexpected access; storing it in S3 Standard wastes money during idle periods. Which class resolves this?$q$,$q$["S3 Intelligent-Tiering, accepting a small monitoring fee for automatic tier movement","S3 Glacier Deep Archive","EBS instead of S3","A fixed choice between Standard and IA with no monitoring"]$q$::jsonb,'0'::jsonb,$q$Intelligent-Tiering automatically moves objects between tiers based on actual access, trading a small monitoring fee for optimal cost regardless of unpredictable patterns.$q$),
('sa-q-104','awssaa',4,'4.1','mcq',2,$q$Which AWS tool specifically checks an account against cost, security, performance, and fault-tolerance best practices, flagging issues like idle load balancers?$q$,$q$["AWS Trusted Advisor","Amazon Route 53","AWS Direct Connect","Amazon CloudFront"]$q$::jsonb,'0'::jsonb,$q$Trusted Advisor evaluates the account across multiple best-practice categories including cost optimization, flagging idle resources like unused load balancers.$q$),
('sa-q-105','awssaa',4,'4.2','mcq',2,$q$A finance team wants a visual breakdown and forecast of AWS spend by service and account over the last six months. Which tool provides this?$q$,$q$["AWS Cost Explorer","AWS Config","Amazon GuardDuty","AWS Shield"]$q$::jsonb,'0'::jsonb,$q$Cost Explorer visualizes historical spend and forecasts future costs broken down by service, account, and other dimensions.$q$);
